/* Generated by the transpiler. Runtime first, then the program. */
#define RT_FILES "src/main.lar", "std/os.lar", "std/text.lar", "std/path.lar", "std/io/files.lar", "std/io/console.lar", "std/io/streams.lar", "src/syntax/ast.lar", "src/semantics/types.lar", "src/semantics/linker.lar", "src/syntax/parser.lar", "src/syntax/lexer.lar", "src/editor/docstore.lar", "src/semantics/analyzer.lar", "src/semantics/expressions.lar", "src/editor/session.lar", "std/json.lar", "std/toml.lar", "src/project/testing.lar", "src/project/cc.lar", "src/editor/lsp.lar", "src/editor/ide.lar", "src/editor/dap.lar", "src/codegen/gen.lar", "src/codegen/runtimeselect.lar", "src/codegen/runtime.lar", "src/codegen/prune.lar", "src/codegen/expressions.lar", "src/codegen/debugmap.lar", "std/lang.lar"
